{
  "name": "PermittingSourceTextSegment",
  "type": "object",
  "description": "Append-only physical PDF page evidence batches. Segments become usable only after the parent source receipt commits their page range. Text extraction does not establish adopted authority.",
  "properties": {
    "registration_key": {
      "type": "string",
      "description": "Deterministic identity: source record, exact archive hash, parser method, and first physical page."
    },
    "source_document_id": {
      "type": "string"
    },
    "source_sha256": {
      "type": "string"
    },
    "archived_file_url": {
      "type": "string"
    },
    "file_bytes": {
      "type": "number"
    },
    "method": {
      "type": "string"
    },
    "page_start": {
      "type": "integer"
    },
    "page_end": {
      "type": "integer"
    },
    "total_pages": {
      "type": "integer"
    },
    "payload_sha256": {
      "type": "string",
      "description": "SHA-256 of canonical identity, page range, and page evidence."
    },
    "pages": {
      "type": "array",
      "minItems": 1,
      "maxItems": 5,
      "items": {
        "type": "object",
        "properties": {
          "page": {
            "type": "integer"
          },
          "text": {
            "type": "string"
          },
          "source_document_id": {
            "type": "string"
          },
          "source_sha256": {
            "type": "string"
          },
          "text_sha256": {
            "type": "string"
          },
          "method": {
            "type": "string"
          },
          "extracted_at": {
            "type": "string",
            "format": "date-time"
          },
          "truncated": {
            "type": "boolean"
          },
          "needs_ocr_review": {
            "type": "boolean"
          }
        },
        "required": [
          "page",
          "text",
          "source_document_id",
          "source_sha256",
          "text_sha256",
          "method",
          "truncated",
          "needs_ocr_review"
        ]
      }
    }
  },
  "required": [
    "registration_key",
    "source_document_id",
    "source_sha256",
    "archived_file_url",
    "file_bytes",
    "method",
    "page_start",
    "page_end",
    "total_pages",
    "payload_sha256",
    "pages"
  ],
  "rls": {
    "create": { "user_condition": { "role": "__permittingsourcetextsegment_backend_only__" } },
    "read": { "user_condition": { "role": "__permittingsourcetextsegment_backend_only__" } },
    "update": { "user_condition": { "role": "__permittingsourcetextsegment_backend_only__" } },
    "delete": { "user_condition": { "role": "__permittingsourcetextsegment_backend_only__" } }
  }
}

{
  "name": "PermittingWorkflowDraft",
  "type": "object",
  "description": "Permitting-only review draft. Never a job, approved requirement or operational workflow. Immutable snapshot; regenerate to create a new version.",
  "properties": {
    "title": {
      "type": "string"
    },
    "status": {
      "type": "string",
      "enum": [
        "draft"
      ],
      "default": "draft"
    },
    "jurisdiction_id": {
      "type": "string"
    },
    "jurisdiction_name": {
      "type": "string"
    },
    "state": {
      "type": "string"
    },
    "review_notes": {
      "type": "string"
    },
    "reviewed_at": {
      "type": "string",
      "format": "date-time"
    },
    "snapshot": {
      "type": "object"
    },
    "project_inputs": {
      "type": "object"
    }
  },
  "required": [
    "title",
    "status",
    "snapshot"
  ],
  "rls": {
    "create": { "user_condition": { "role": "__permittingworkflowdraft_backend_only__" } },
    "read": { "user_condition": { "role": "__permittingworkflowdraft_backend_only__" } },
    "update": { "user_condition": { "role": "__permittingworkflowdraft_backend_only__" } },
    "delete": { "user_condition": { "role": "__permittingworkflowdraft_backend_only__" } }
  }
}

{
  "name": "PortalMessage",
  "type": "object",
  "description": "Two-way customer portal thread. Messages flow customer<->staff per customer account; kind distinguishes plain messages from structured events (estimate approval, revision request, payment notice). Backend-only; written through customerPortalAction.",
  "properties": {
    "schema_version": {
      "type": "number",
      "default": 1
    },
    "creation_request_key": {
      "type": "string",
      "description": "Stable retry-safe receipt for one message."
    },
    "customer_id": {
      "type": "string"
    },
    "portal_link_id": {
      "type": "string"
    },
    "author_side": {
      "type": "string",
      "enum": [
        "customer",
        "staff",
        "system"
      ]
    },
    "author_name": {
      "type": "string"
    },
    "author_email": {
      "type": "string"
    },
    "kind": {
      "type": "string",
      "enum": [
        "message",
        "estimate_approved",
        "estimate_revision_requested",
        "payment_notice",
        "job_revision_requested",
        "system"
      ],
      "default": "message"
    },
    "body": {
      "type": "string"
    },
    "attachment_name": {
      "type": "string"
    },
    "attachment_url": {
      "type": "string"
    },
    "attachment_mime": {
      "type": "string"
    },
    "related_kind": {
      "type": "string",
      "enum": [
        "estimate",
        "invoice",
        "work_order",
        "none"
      ],
      "default": "none"
    },
    "related_id": {
      "type": "string"
    },
    "related_label": {
      "type": "string"
    },
    "read_by_staff": {
      "type": "boolean",
      "default": false
    },
    "read_by_customer": {
      "type": "boolean",
      "default": false
    }
  },
  "required": [
    "creation_request_key",
    "customer_id",
    "author_side",
    "body"
  ],
  "rls": {
    "create": {
      "user_condition": {
        "role": "__portal_message_backend_only__"
      }
    },
    "read": {
      "user_condition": {
        "role": "__portal_message_backend_only__"
      }
    },
    "update": {
      "user_condition": {
        "role": "__portal_message_backend_only__"
      }
    },
    "delete": {
      "user_condition": {
        "role": "__portal_message_backend_only__"
      }
    }
  }
}

{
  "name": "PricingMode",
  "type": "object",
  "properties": {
    "active_mode": {
      "type": "string",
      "enum": [
        "tier",
        "cost_plus"
      ],
      "default": "tier",
      "description": "Which pricing system is currently active. 'tier' = % Tier Markups (default). 'cost_plus' = Cost-Plus."
    },
    "notes": {
      "type": "string"
    }
  },
  "required": [
    "active_mode"
  ],
  "rls": {
    "create": { "user_condition": { "role": "__pricingmode_backend_only__" } },
    "read": { "user_condition": { "role": "__pricingmode_backend_only__" } },
    "update": { "user_condition": { "role": "__pricingmode_backend_only__" } },
    "delete": { "user_condition": { "role": "__pricingmode_backend_only__" } }
  }
}

{
  "name": "PricingModifier",
  "type": "object",
  "description": "CoreBridge-style custom property / variable-rate modifier attachable to catalog parts and estimate lines. A modifier captures extra input (text, number, select, checkbox, or formula) and can adjust price via rate tables, a formula, setup fees, minimum charges, and waste factors.",
  "properties": {
    "name": {
      "type": "string",
      "description": "Internal modifier name (unique key used in formulas and part configuration)."
    },
    "label": {
      "type": "string",
      "description": "Customer/operator-facing label shown on the estimate input form."
    },
    "input_type": {
      "type": "string",
      "description": "Input widget type: text | number | select | checkbox | formula. 'select' options come from ModifierOption rows; 'formula' derives its value from formula_text instead of user input."
    },
    "can_use_in_pricing": {
      "type": "boolean",
      "default": false,
      "description": "When true this modifier's value/rates may feed the pricing waterfall."
    },
    "rates": {
      "type": "array",
      "description": "Variable rate table rows: {label:string, retail:number, cost:number, per_unit:string}. Selected/matched row supplies the retail and cost rates and the unit basis the rate applies to.",
      "items": {
        "type": "object",
        "properties": {
          "label": {
            "type": "string"
          },
          "retail": {
            "type": "number"
          },
          "cost": {
            "type": "number"
          },
          "per_unit": {
            "type": "string"
          }
        },
        "additionalProperties": true
      }
    },
    "formula_text": {
      "type": "string",
      "description": "Formula expression (CoreBridge variable-rate syntax) evaluated when input_type is formula or when pricing derives from modifier inputs."
    },
    "include_setup_fee": {
      "type": "boolean",
      "default": false,
      "description": "When true the modifier contributes a flat setup fee in addition to its unit-rate price."
    },
    "min_charge": {
      "type": "number",
      "default": 0,
      "description": "Floor for this modifier's total price contribution; 0 = no minimum."
    },
    "affects_waste": {
      "type": "boolean",
      "default": false,
      "description": "When true the modifier value scales the part's waste/overage factor."
    },
    "inventoried_part_type": {
      "type": "string",
      "description": "Optional part-type key limiting which inventoried catalog parts this modifier may attach to."
    },
    "pricing_tier_id": {
      "type": "string",
      "description": "Optional PricingTierMatrix/tier row scoping this modifier's rates to a customer pricing tier."
    },
    "display_order": {
      "type": "number",
      "default": 0,
      "description": "Order the modifier input renders within its part's modifier list."
    },
    "status": {
      "type": "string",
      "description": "Lifecycle status (e.g. active, archived). Free-form string; treated as active when unset."
    }
  },
  "required": [],
  "rls": {
    "create": {
      "user_condition": {
        "role": "__pricingmodifier_backend_only__"
      }
    },
    "read": {
      "user_condition": {
        "role": "__pricingmodifier_backend_only__"
      }
    },
    "update": {
      "user_condition": {
        "role": "__pricingmodifier_backend_only__"
      }
    },
    "delete": {
      "user_condition": {
        "role": "__pricingmodifier_backend_only__"
      }
    }
  }
}

{
  "name": "PricingTemplate",
  "type": "object",
  "description": "Named quantity-break x customer-tier margin chart scoped to a unit category (CoreBridge 'Pricing Templates' analog \u2014 17 seed reference shapes). A catalog part selects a template on its Pricing Tiers tab; the pricing engine resolves the matching qty bracket, then applies the customer's tier markup_pct \u2014 or the market-based retail/discount chart when market_based is set. Backend-only: all access goes through staffEntityWrite/admin functions.",
  "properties": {
    "name": {
      "type": "string",
      "description": "Display label for this margin chart, e.g. 'Banner SqFt \u2014 Standard' or 'Retail Parts qty chart'."
    },
    "unit_category": {
      "type": "string",
      "description": "Pricing-unit category this chart covers (SqFt, LinFt, Each, Hourly, Pixels, ...). Only parts whose pricing unit matches may select this template."
    },
    "breaks": {
      "type": "array",
      "description": "Quantity brackets in ascending qty order. When order qty >= bracket qty, that bracket's tier_markups chart applies.",
      "items": {
        "type": "object",
        "additionalProperties": true,
        "properties": {
          "qty": {
            "type": "number",
            "description": "Minimum quantity that unlocks this bracket."
          },
          "tier_markups": {
            "type": "object",
            "description": "Markup percent per customer tier for this bracket, keyed by MarkupTier.tier_name (e.g. {\"General Public\": 50, \"Wholesale\": 30}). Values are markup_pct numbers where 50 = sell at cost x 1.50.",
            "additionalProperties": {
              "type": "number"
            }
          }
        }
      }
    },
    "market_based": {
      "type": "boolean",
      "default": false,
      "description": "When true, tier_markups values are interpreted as market-based retail/discount chart entries instead of cost-plus markup percents."
    },
    "description": {
      "type": "string",
      "description": "Optional admin notes on when or where this chart should be used."
    },
    "sort": {
      "type": "number",
      "default": 0,
      "description": "Display order in template pickers."
    },
    "status": {
      "type": "string",
      "enum": [
        "active",
        "inactive"
      ],
      "default": "active",
      "description": "Inactive templates are hidden from pickers and ignored by the pricing engine."
    }
  },
  "rls": {
    "create": {
      "user_condition": {
        "role": "__pricingtemplate_backend_only__"
      }
    },
    "read": {
      "user_condition": {
        "role": "__pricingtemplate_backend_only__"
      }
    },
    "update": {
      "user_condition": {
        "role": "__pricingtemplate_backend_only__"
      }
    },
    "delete": {
      "user_condition": {
        "role": "__pricingtemplate_backend_only__"
      }
    }
  }
}

{
  "name": "PricingTierMatrix",
  "type": "object",
  "properties": {
    "name": {
      "type": "string",
      "description": "Display label for this matrix row, e.g. 'Retail / Banners qty breaks'."
    },
    "status": {
      "type": "string",
      "enum": [
        "active",
        "inactive"
      ],
      "default": "active",
      "description": "Inactive rows are ignored by the pricing engine."
    },
    "customer_tier": {
      "type": "string",
      "description": "MarkupTier this row applies to \u2014 tier_name, tier_number, or record id. Blank means the row is a category-wide default that applies to every tier."
    },
    "category": {
      "type": "string",
      "description": "Sign category key (MarkupCategory.category_key) this row prices. Blank means the row is a tier-wide default covering every category."
    },
    "markup_pct": {
      "type": "number",
      "default": 0,
      "description": "Markup percent over unit cost. 50 = sell at cost x 1.50. Ignored when a matching per_unit_breaks bracket applies."
    },
    "pricing_mode": {
      "type": "string",
      "enum": [
        "markup",
        "market"
      ],
      "default": "markup",
      "description": "Pricing path for this row. 'markup' prices at markup_pct over unit cost. 'market' prices at market_retail less market_discount_pct; a qualifying per_unit_breaks bracket still wins when it prices lower than the market price."
    },
    "market_retail": {
      "type": "number",
      "description": "Market-based pricing: prevailing retail unit price this row tracks. Required for pricing_mode = 'market'; a market row without it falls back to markup pricing."
    },
    "market_discount_pct": {
      "type": "number",
      "default": 0,
      "description": "Market-based pricing: percent off market_retail. 10 = sell at 90% of retail."
    },
    "minimum_charge": {
      "type": "number",
      "default": 0,
      "description": "Line-level floor price. When the computed extension lands above zero but below this amount, the line is raised to the minimum."
    },
    "per_unit_breaks": {
      "type": "array",
      "description": "Quantity price breaks: when qty >= bracket qty, the bracket unit_price replaces markup_pct pricing.",
      "items": {
        "type": "object",
        "additionalProperties": true,
        "properties": {
          "qty": {
            "type": "number",
            "description": "Minimum quantity that unlocks this bracket."
          },
          "unit_price": {
            "type": "number",
            "description": "Sell price per unit inside this bracket."
          }
        }
      }
    },
    "formula_modifiers": {
      "type": "array",
      "description": "Ordered unit-price adjustments applied after markup/market/break resolution, evaluated left to right. Each item: {type: 'add_pct'|'mul'|'add_flat'|'min'|'max', value} \u2014 add_pct: price x (1+value/100); mul: price x value; add_flat: price + value; min: floor at value; max: cap at value.",
      "items": {
        "type": "object",
        "additionalProperties": true,
        "properties": {
          "type": {
            "type": "string",
            "enum": [
              "add_pct",
              "mul",
              "add_flat",
              "min",
              "max"
            ]
          },
          "value": {
            "type": "number"
          }
        }
      }
    },
    "effective_from": {
      "type": "string",
      "format": "date",
      "description": "First date (YYYY-MM-DD) this row is effective. Blank = no start bound."
    },
    "effective_to": {
      "type": "string",
      "format": "date",
      "description": "Last date (YYYY-MM-DD, inclusive) this row is effective. Blank = no end bound."
    },
    "updated_by": {
      "type": "string",
      "description": "Email of the staff user who last saved this row (audit)."
    },
    "updated_note": {
      "type": "string",
      "description": "Optional change note left by the last editor (audit)."
    },
    "sort_order": {
      "type": "number",
      "default": 0
    }
  },
  "required": [
    "name"
  ],
  "rls": {
    "create": {
      "user_condition": {
        "role": "__pricingtiermatrix_backend_only__"
      }
    },
    "read": {
      "user_condition": {
        "role": "__pricingtiermatrix_backend_only__"
      }
    },
    "update": {
      "user_condition": {
        "role": "__pricingtiermatrix_backend_only__"
      }
    },
    "delete": {
      "user_condition": {
        "role": "__pricingtiermatrix_backend_only__"
      }
    }
  }
}

{
  "name": "ProductActivity",
  "type": "object",
  "description": "Append-only per-product audit trail: operational_status/substatus changes, proof events, due-date moves, assignment and priority edits, notes, estimate\u2192WO conversions, and manual overrides \u2014 one row per product change, written by service-role backends (product history tab / order history feeds read it). Rows are immutable; corrections are new rows, never edits.",
  "properties": {
    "schema_version": {
      "type": "number",
      "default": 1
    },
    "creation_request_key": {
      "type": "string",
      "description": "Stable retry-safe receipt for one audit row so a lost create response never double-writes history."
    },
    "work_order_id": {
      "type": "string",
      "description": "Parent WorkOrder id \u2014 the primary filter/grouping key for a job's product history (queries always filter on this first)."
    },
    "product_id": {
      "type": "string",
      "description": "id inside WorkOrder.products[] (or the linked BuilderProduct id) the event concerns."
    },
    "product_label": {
      "type": "string",
      "description": "Display name of the product captured at write time so history stays readable after renames."
    },
    "event_type": {
      "type": "string",
      "enum": [
        "status_change",
        "substatus_change",
        "proof_event",
        "proof_approved",
        "proof_changes_requested",
        "proof_superseded",
        "due_date_change",
        "assignment_change",
        "priority_change",
        "note",
        "conversion",
        "override",
        "price_override"
      ]
    },
    "actor_type": {
      "type": "string",
      "enum": [
        "staff",
        "customer",
        "vendor",
        "system"
      ],
      "default": "staff",
      "description": "Actor class \u2014 drives order-history coloring (staff black / customer green / vendor blue / system grey)."
    },
    "actor_label": {
      "type": "string",
      "description": "Display name or email of who caused the event; system rows name the function/sync that wrote them."
    },
    "from_value": {
      "type": "string",
      "description": "Value before the change, string-rendered (empty when not applicable, e.g. notes/conversions)."
    },
    "to_value": {
      "type": "string",
      "description": "Value after the change, string-rendered."
    },
    "note": {
      "type": "string",
      "description": "Free-form context \u2014 note text for note events, override reason, or extra detail."
    },
    "occurred_at": {
      "type": "string",
      "description": "ISO timestamp the change happened; history sorts on this (chronological)."
    },
    "details": {
      "type": "object",
      "additionalProperties": true,
      "description": "Structured extras: which product field changed, patch keys, proof version, source module."
    }
  },
  "required": [
    "work_order_id",
    "product_id",
    "event_type",
    "occurred_at"
  ],
  "rls": {
    "create": {
      "user_condition": {
        "role": "__product_activity_backend_only__"
      }
    },
    "read": {
      "user_condition": {
        "role": "__product_activity_backend_only__"
      }
    },
    "update": {
      "user_condition": {
        "role": "__product_activity_backend_only__"
      }
    },
    "delete": {
      "user_condition": {
        "role": "__product_activity_backend_only__"
      }
    }
  }
}

{
  "name": "ProductSubstatus",
  "type": "object",
  "description": "Registry of persistent custom substatus tags for products (CoreBridge-style operational substatus picklist). Products carry applied tags on products[].quick_tags[]; each registry row is one managed picklist option \u2014 a display label, chip color, the module keys the tag applies to, and picklist ordering. Backend-only \u2014 read/written via service-role functions.",
  "properties": {
    "name": {
      "type": "string",
      "description": "Tag label as stored on products[].quick_tags[] (e.g. 'Rush', 'Waiting on Customer')."
    },
    "color": {
      "type": "string",
      "description": "Hex display color for the tag chip (e.g. '#f59e0b')."
    },
    "applies_to": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "Module keys this tag is offered in (e.g. design, production, installation); empty means the tag is offered in every module."
    },
    "sort": {
      "type": "number",
      "default": 0,
      "description": "Display ordering of this tag in the picklist."
    },
    "status": {
      "type": "string",
      "default": "active",
      "description": "Lifecycle state \u2014 active | archived."
    }
  },
  "required": [],
  "rls": {
    "create": {
      "user_condition": {
        "role": "__productsubstatus_backend_only__"
      }
    },
    "read": {
      "user_condition": {
        "role": "__productsubstatus_backend_only__"
      }
    },
    "update": {
      "user_condition": {
        "role": "__productsubstatus_backend_only__"
      }
    },
    "delete": {
      "user_condition": {
        "role": "__productsubstatus_backend_only__"
      }
    }
  }
}

{
  "name": "Project",
  "type": "object",
  "description": "Painting estimator project (paint / paint mask / supplies / labor).",
  "properties": {
    "client_name": {
      "type": "string",
      "description": "Client company or person name"
    },
    "customer_id": {
      "type": "string",
      "description": "Linked shared Customer record id."
    },
    "project_name": {
      "type": "string",
      "description": "Name of the project"
    },
    "estimate_number": {
      "type": "string",
      "description": "Unique estimate number for tracking"
    },
    "hyperlink": {
      "type": "string",
      "description": "Optional hyperlink related to the project"
    },
    "creation_request_key": {
      "type": "string",
      "description": "Internal retry receipt used only to make the first Painting Builder source create idempotent."
    },
    "status": {
      "type": "string",
      "enum": [
        "draft",
        "calculated",
        "archived"
      ],
      "default": "draft",
