  "rls": {
    "create": {
      "user_condition": {
        "role": "__sop_backend_only__"
      }
    },
    "read": {
      "user_condition": {
        "role": "__sop_backend_only__"
      }
    },
    "update": {
      "user_condition": {
        "role": "__sop_backend_only__"
      }
    },
    "delete": {
      "user_condition": {
        "role": "__sop_backend_only__"
      }
