{
  "name": "SourceCollectionQueue",
  "type": "object",
  "description": "Collection-queue row tracking source-gathering progress for one jurisdiction. Seeded with all KY and OH counties plus incorporated KY cities and OH cities/villaries. Boone County KY is marked verified_current with its completed archive summary.",
  "properties": {
    "jurisdiction_name": {
      "type": "string",
      "description": "Name of the jurisdiction (e.g. 'Boone County', 'Florence')."
    },
    "state": {
      "type": "string",
      "description": "State abbreviation (KY, OH)."
    },
    "jurisdiction_type": {
      "type": "string",
      "enum": [
        "county",
        "city",
        "village",
        "township",
        "planning_unit"
      ],
      "default": "county",
      "description": "Type of jurisdiction."
    },
    "parent_county_name": {
      "type": "string",
      "description": "Name of the parent county for non-county jurisdictions (city/village/township), when known from the static seed list. Blank for county rows."
    },
    "authority_note": {
      "type": "string",
      "description": "Plain-language note about the jurisdiction's current sign-regulation authority status."
    },
    "source_category": {
      "type": "string",
      "enum": [
        "sign_regulations",
        "zoning_code",
        "forms",
        "fee_schedule",
        "portal",
        "contacts",
        "electrical",
        "right_of_way",
        "other"
      ],
      "default": "sign_regulations",
      "description": "Primary source category being collected for this queue row."
    },
    "status": {
      "type": "string",
      "enum": [
        "not_started",
        "source_discovery",
        "sources_found",
        "archive_incomplete",
        "extraction_pending",
        "verification_pending",
        "verified_current",
        "partial_gaps",
        "blocked",
        "monitoring_enabled",
        "re_review_required"
      ],
      "default": "not_started",
      "description": "Collection progress status."
    },
    "missing_next": {
      "type": "string",
      "description": "Short human-readable description of exactly what is missing next."
    },
    "source_document_refs": {
      "type": "array",
      "description": "List of PermittingSourceDocument record ids linked to this jurisdiction's collection.",
      "items": {
        "type": "string"
      },
      "default": []
    },
    "last_activity": {
      "type": "string",
      "format": "date-time",
      "description": "When the queue row was last updated."
    },
    "research_request_id": {
      "type": "string",
      "description": "Permitting Research app ResearchRequest id currently associated with this queue row."
    },
    "research_requested_at": {
      "type": "string",
      "format": "date-time",
      "description": "When the current research request was successfully created."
    },
    "research_dispatch_version": {
      "type": "string",
      "description": "Dispatcher contract version used to enqueue this row."
    },
    "research_dispatch_token": {
      "type": "string",
      "description": "Short-lived reservation token used to prevent concurrent dispatchers from enqueueing the same queue row."
    },
    "research_dispatch_attempts": {
      "type": "integer",
      "default": 0,
      "description": "Number of automated attempts to hand this queue row to the Permitting Research app."
    },
    "dispatch_rank": {
      "type": "number",
      "description": "Dispatch ordering key: miles from downtown Cincinnati (Census gazetteer centroid). Lower ranks dispatch first; rows without a rank fall back to the Ohio-first ordering."
    }
  },
  "required": [
    "jurisdiction_name",
    "state"
  ],
  "rls": {
    "create": {
      "user_condition": {
        "role": "admin"
      }
    },
    "read": {
      "$or": [
        {
          "user_condition": {
            "role": "admin"
          }
        },
        {
          "user_condition": {
            "role": "user"
          }
        }
      ]
    },
    "update": {
      "user_condition": {
        "role": "admin"
      }
    },
    "delete": {
      "user_condition": {
        "role": "admin"
      }
    }
  }
}

{
  "name": "SourceMonitorState",
  "type": "object",
  "description": "One row per monitored PermittingSourceDocument. Tracks cheap programmatic HTTP checks (ETag/Last-Modified/Content-Length/hash) so the platform AI is only invoked when a source actually changes. Monitor-enabled is Boone County only for the initial pass; statewide activation is a later phase.",
  "properties": {
    "source_document_id": {
      "type": "string",
      "description": "PermittingSourceDocument record id this monitor row tracks."
    },
    "jurisdiction_name": {
      "type": "string",
      "description": "Cached jurisdiction name for filtering without a join."
    },
    "jurisdiction_id": {
      "type": "string",
      "description": "Cached JurisdictionProfile record id."
    },
    "official_url": {
      "type": "string",
      "description": "URL checked by the scanner. Copied from PermittingSourceDocument.official_url."
    },
    "source_title": {
      "type": "string",
      "description": "Cached source document title for display."
    },
    "source_type": {
      "type": "string",
      "description": "Cached source_type from PermittingSourceDocument for cadence defaults."
    },
    "authority_classification": {
      "type": "string",
      "description": "Cached authority_classification from PermittingSourceDocument."
    },
    "check_method": {
      "type": "string",
      "enum": [
        "etag",
        "last_modified",
        "content_length",
        "hash"
      ],
      "default": "hash",
      "description": "Primary cheap-check method used. Hash is the fallback when headers are absent."
    },
    "last_known_hash": {
      "type": "string",
      "description": "SHA-256 of the last observed response body. Compared on every scan."
    },
    "last_known_etag": {
      "type": "string",
      "description": "Last observed ETag header value."
    },
    "last_known_last_modified": {
      "type": "string",
      "description": "Last observed Last-Modified header value."
    },
    "last_known_content_length": {
      "type": "number",
      "description": "Last observed Content-Length header value."
    },
    "last_successful_check": {
      "type": "string",
      "format": "date-time",
      "description": "When the last cheap check completed (change or no-change)."
    },
    "last_changed": {
      "type": "string",
      "format": "date-time",
      "description": "When a change was last detected."
    },
    "last_change_summary": {
      "type": "object",
      "additionalProperties": true,
      "description": "JSON summary of the last change: old/new hash, old/new content length, changed-links set, AI regulatory-impact assessment, affected rules count."
    },
    "failure_count": {
      "type": "number",
      "default": 0,
      "description": "Consecutive fetch failures. Reset to 0 on success."
    },
    "last_http_status": {
      "type": "string",
      "description": "HTTP status of the last attempt (e.g. '200', '404', 'timeout')."
    },
    "last_error": {
      "type": "string",
      "description": "Last error message (never contains secrets)."
    },
    "may_affect_regulatory_data": {
      "type": "boolean",
      "default": false,
      "description": "True when the last change was assessed as potentially affecting regulatory requirements."
    },
    "staff_review_required": {
      "type": "boolean",
      "default": false,
      "description": "True when staff review is needed (regulatory impact or broken source)."
    },
    "schedule_cadence": {
      "type": "string",
      "enum": [
        "volatile",
        "moderate",
        "stable",
        "immutable"
      ],
      "default": "moderate",
      "description": "Check cadence. volatile=weekly, moderate=monthly, stable=quarterly, immutable=yearly."
    },
    "next_check_due": {
      "type": "string",
      "format": "date-time",
      "description": "When the next scan should run. Computed from last_successful_check + cadence."
    },
    "monitor_enabled": {
      "type": "boolean",
      "default": false,
      "description": "Whether this source is actively monitored. Boone County only for the initial pass."
    }
  },
  "required": [
    "source_document_id",
    "official_url"
  ],
  "rls": {
    "create": { "user_condition": { "role": "__sourcemonitorstate_backend_only__" } },
    "read": { "user_condition": { "role": "__sourcemonitorstate_backend_only__" } },
    "update": { "user_condition": { "role": "__sourcemonitorstate_backend_only__" } },
    "delete": { "user_condition": { "role": "__sourcemonitorstate_backend_only__" } }
  }
}

{
  "name": "StoreCreditLedger",
  "type": "object",
  "description": "Append-only in-store credit ledger (G-09/A-35): one signed row per credit event \u2014 issuance, application to an invoice, expiry, or void. Customer.in_store_credit_balance is a denormalized cache of SUM(amount) over the customer's rows; corrections are reversing rows, never edits. Written by service-role backends; customer-facing credit views read it.",
  "properties": {
    "schema_version": {
      "type": "number",
      "default": 1
    },
    "creation_request_key": {
      "type": "string",
      "description": "Stable retry-safe receipt so a lost create response never double-posts credit."
    },
    "customer_id": {
      "type": "string",
      "description": "Customer the ledger row belongs to \u2014 the primary filter/grouping key."
    },
    "kind": {
      "type": "string",
      "enum": [
        "credit_issued",
        "credit_applied",
        "credit_expired",
        "credit_voided"
      ],
      "description": "Event kind (storeCreditModel CREDIT_LEDGER_KINDS)."
    },
    "amount": {
      "type": "number",
      "description": "Signed amount in dollars \u2014 positive on issue, negative on apply/expire/void."
    },
    "amount_cents": {
      "type": "number",
      "description": "Signed amount in integer cents \u2014 the canonical ledger value (amount is a display mirror)."
    },
    "ref": {
      "type": "string",
      "description": "For credit_voided rows: id of the ledger row being reversed."
    },
    "reversed_kind": {
      "type": "string",
      "description": "For credit_voided rows: the kind of the reversed row."
    },
    "reason": {
      "type": "string",
      "description": "Free-text reason (issue memo / void justification)."
    },
    "actor": {
      "type": "string",
      "description": "Email/id of the staff member (or system) that posted the row."
    },
    "invoice_id": {
      "type": "string",
      "description": "For credit_applied rows: the invoice the credit was applied to."
    },
    "balance_after": {
      "type": "number",
      "description": "Running customer balance in dollars immediately after this row posted."
    },
    "occurred_at": {
      "type": "string",
      "format": "date-time",
      "description": "Effective timestamp of the credit event (defaults to write time)."
    }
  },
  "required": [
    "customer_id",
    "kind",
    "amount"
  ],
  "rls": {
    "create": {
      "user_condition": {
        "role": "__store_credit_ledger_backend_only__"
      }
    },
    "update": {
      "user_condition": {
        "role": "__store_credit_ledger_backend_only__"
      }
    },
    "delete": {
      "user_condition": {
        "role": "__store_credit_ledger_backend_only__"
      }
    },
    "read": {
      "user_condition": {
        "role": "__store_credit_ledger_backend_only__"
      }
    }
  }
}
